// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(
        uint64 ts1,
        uint64 number,
        uint256 basefee,
        bytes32 hash,
        uint64 seq,
        bytes32 batcher,
        uint256 overhead,
        uint256 scalar
    ) public {
        vm.assume(ts1 != 0);
        vm.prank(0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);
        c.setL1BlockValues(0, ts1, basefee, hash, seq, batcher, overhead, scalar);
        vm.prank(0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);
        c.setL1BlockValues(number, ts1 + 1, basefee, hash, seq, batcher, overhead, scalar);
        assertEq(c.timestamp(), ts1 + 1);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) external {
        bytes memory data = abi.encodeWithSelector(
            c.setL1BlockValues.selector,
            _number, _timestamp, _basefee, _hash,
            _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar
        );
        bool ok;
        (ok, ) = address(c).call(data);
        assert(!ok);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function check(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _seq, bytes32 _batcherHash, uint256 _overhead, uint256 _scalar) external {
        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(
                c.setL1BlockValues.selector,
                _number, _timestamp, _basefee, _hash, _seq, _batcherHash, _overhead, _scalar
            )
        );
        assert(!ok);
    }
}
